43→test('SM4: resolver success with conflict markers still refuses and reaps the stage', async () => {
44→  for (const [taskId, resolve] of [
45→    ['sm-markers', async () => ({ status: 'resolved' })],
46→    ['sm-marker-evasion', async ({ absolutePath }) => { writeFileSync(absolutePath, 'export const ok = 1;\n<<<<<<<ours\n'); return { status: 'resolved' }; }],
47→  ]) {
48→    const root = repo(); const resolver = { maxFileBytes: 4096, identity: () => ({ tool: 'fake-mergiraf', version: 'test' }), resolve };
49→    const { coordinator, handle } = await accepted(root, taskId, 'export const values = { alpha: 2 };\n', resolver);
50→    write(root, 'src/value.js', 'export const values = { alpha: 3 };\n'); commit(root, 'main diverges'); const before = git(['rev-parse', 'HEAD'], root);
51→    await assert.rejects(coordinator.integrate(handle.id, { strategy: 'structured' }), (error) => error.code === 'structured_unresolved');
52→    assert.equal(git(['rev-parse', 'HEAD'], root), before); assert.equal(existsSync(join(root, '.baton', 'integrate')), false);
53→  }
54→});
