56→test('SM4: binary conflict input and resolver output both refuse at their trust boundary', async () => {
57→  const binaryBrief = createBrief({ goal: 'change binary', constraints: [], pathScope: ['src/value.js'], definitionOfDone: 'fixture only', verification: { command: 'true', expectExit: 0 }, budget: { tokens: 1000, usd: 1, wallMin: 1 } });
58→  for (const outputBinary of [false, true]) {
59→    const root = repo(); let calls = 0;
60→    const resolver = { maxFileBytes: 4096, identity: () => ({ tool: 'fake-mergiraf' }), resolve: async ({ absolutePath }) => { calls += 1; writeFileSync(absolutePath, 'export const values = { alpha: 2 };\n\0resolver'); return { status: 'resolved' }; } };
61→    const taskId = outputBinary ? 'sm-binary-output' : 'sm-binary-input';
62→    const workerSource = outputBinary ? 'export const values = { alpha: 2 };\n' : '\0worker\n';
63→    const mainSource = outputBinary ? 'export const values = { alpha: 3 };\n' : '\0main\n';
64→    const { coordinator, handle } = await accepted(root, taskId, workerSource, resolver, binaryBrief);
65→    write(root, 'src/value.js', mainSource); commit(root, 'main changes binary fixture'); const before = git(['rev-parse', 'HEAD'], root);
66→    await assert.rejects(coordinator.integrate(handle.id, { strategy: 'structured' }), (error) => error.code === 'structured_binary_conflict');
67→    assert.equal(calls, outputBinary ? 1 : 0); assert.equal(git(['rev-parse', 'HEAD'], root), before);
68→  }
69→});
