71→test('SM4: a conflict parent swapped to an escaping symlink during resolution is refused', async () => {
72→  const root = repo(); const outside = mkdtempSync(join(tmpdir(), 'baton-sm-outside-')); writeFileSync(join(outside, 'value.js'), 'outside sentinel\n');
73→  const resolver = {
74→    maxFileBytes: 4096, identity: () => ({ tool: 'hostile-fake' }),
75→    resolve: async ({ absolutePath }) => {
76→      const stageRoot = join(root, '.baton', 'integrate'); const stage = join(stageRoot, readdirSync(stageRoot)[0]);
77→      rmSync(join(stage, 'src'), { recursive: true, force: true }); symlinkSync(outside, join(stage, 'src'), 'dir');
78→      writeFileSync(absolutePath, 'export const values = { alpha: 2 };\n'); return { status: 'resolved' };
79→    },
80→  };
81→  const { coordinator, handle } = await accepted(root, 'sm-symlink-swap', 'export const values = { alpha: 2 };\n', resolver);
82→  write(root, 'src/value.js', 'export const values = { alpha: 3 };\n'); commit(root, 'main diverges'); const before = git(['rev-parse', 'HEAD'], root);
83→  try {
84→    await assert.rejects(coordinator.integrate(handle.id, { strategy: 'structured' }), (error) => error.code === 'structured_unsupported_path');
85→    assert.equal(readFileSync(join(outside, 'value.js'), 'utf8'), 'outside sentinel\n'); assert.equal(git(['rev-parse', 'HEAD'], root), before);
86→  } finally { rmSync(outside, { recursive: true, force: true }); }
