  const sha = target.sha ?? task.integration.afterSha;
  if (typeof remote !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(remote)) {
    throw new PublicationError('remote must be a credential-free git remote name', 'invalid_remote');
  }

