1→// referee.mjs — THE TRUST GATE. Re-runs the task's *pinned* verification command in a
2→// fresh sandbox the worker never controlled, and derives a Verdict the coordinator can
3→// actually trust. The worker's self-reported exit code is used only to detect
4→// divergence, never as evidence of anything (R2).
5→//
6→// D6 (spec/RECONCILIATION.md, authoritative — resolves red workers-trust#1/#4): the
7→// freshness guard is MANDATORY, not opt-in. `task.workerWorktreeDir` is REQUIRED —
8→// `verify()` rejects if it's missing (distinct from rejecting because it EQUALS
9→// sandbox.dir, which is `SameWorktreeError`).
10→
11→import { spawn } from 'node:child_process';
12→
13→export class SameWorktreeError extends Error {
14→  constructor(message) { super(message); this.name = 'SameWorktreeError'; }
15→}
16→
17→// Commands containing real shell control operators (chaining, pipes, redirects,
18→// substitution) need genuine `sh -c` semantics. Everything else is tokenized and
19→// exec'd directly, without a shell, which sidesteps a real POSIX-shell quirk: a
20→// command whose LAST argument is a `"..."`-wrapped payload that itself contains
21→// escaped double quotes (e.g. a `node -e "console.log(\"...json...\")"` coverage
22→// reporter) gets that payload's own string-literal quoting stripped/mangled by a
23→// second layer of shell parsing under `sh -c` — no POSIX-compliant shell avoids
24→// this, since it is standard (if surprising) double-quote nesting behavior.
25→function looksLikeSimpleCommand(command) {
26→  return !/[|&;<>`]|\$\(/.test(command);
27→}
28→
29→/** Whitespace-splits `command` into argv, treating a `"`/`'`-delimited span (matched
30→ * greedily against the LAST occurrence of that quote character in the string) as one
31→ * literal token — no escape-processing inside it, so an embedded `\"` survives intact
32→ * for the invoked program's OWN parser (e.g. Node's `-e` argument) to interpret. */
33→function tokenize(command) {
34→  const tokens = [];
35→  let i = 0;
36→  const n = command.length;
37→  while (i < n) {
38→    while (i < n && /\s/.test(command[i])) i += 1;
39→    if (i >= n) break;
40→    const ch = command[i];
41→    if (ch === '"' || ch === "'") {
42→      const lastQuote = command.lastIndexOf(ch);
43→      if (lastQuote > i) {
44→        tokens.push(command.slice(i + 1, lastQuote));
45→        i = lastQuote + 1;
46→        continue;
47→      }
48→    }
49→    let j = i;
50→    while (j < n && !/\s/.test(command[j])) j += 1;
51→    tokens.push(command.slice(i, j));
52→    i = j;
53→  }
54→  return tokens;
55→}
56→
57→function runCommand(command, cwd, timeoutMs) {
58→  return new Promise((resolve) => {
59→    const preferDirect = looksLikeSimpleCommand(command);
60→    const directArgv = preferDirect ? tokenize(command) : [];
61→    let usingDirect = preferDirect && directArgv.length > 0;
62→
63→    const spawnDirect = () => spawn(directArgv[0], directArgv.slice(1), { cwd, detached: true });
64→    const spawnShell = () => spawn('sh', ['-c', command], { cwd, detached: true });
65→
66→    let child = usingDirect ? spawnDirect() : spawnShell();
67→    const chunks = [];
68→    let settled = false;
69→    let timedOut = false;
70→    let timer;
71→
72→    const finish = (exitCode) => {
73→      if (settled) return;
74→      settled = true;
75→      clearTimeout(timer);
76→      resolve({ exitCode: timedOut ? null : exitCode, output: Buffer.concat(chunks).toString('utf8'), timedOut });
77→    };
78→
79→    const armTimer = () => {
80→      timer = setTimeout(() => {
81→        timedOut = true;
82→        try { process.kill(-child.pid, 'SIGKILL'); } catch { try { child.kill('SIGKILL'); } catch { /* noop */ } }
83→      }, timeoutMs);
84→    };
85→
86→    const wire = () => {
87→      child.stdout?.on('data', (d) => chunks.push(d));
88→      child.stderr?.on('data', (d) => chunks.push(d));
89→      child.on('error', (err) => {
90→        // The direct-exec path assumed the first token names a real executable on PATH;
91→        // if that assumption was wrong (ENOENT), fall back to a real shell once.
92→        if (usingDirect && err && err.code === 'ENOENT') {
93→          usingDirect = false;
94→          clearTimeout(timer);
95→          child = spawnShell();
96→          armTimer();
97→          wire();
98→          return;
99→        }
100→        finish(null);
101→      });
102→      child.on('close', (code) => finish(code));
103→    };
104→
105→    armTimer();
106→    wire();
107→  });
108→}
109→
110→/**
111→ * Re-derive the truth of a worker's result.
112→ * @param {object} task
113→ * @param {object} result
114→ * @param {{dir:string, sha:string, cleanup:() => Promise<void>}} sandbox
115→ * @param {{baseSandbox?: object, requireRedGreen?: boolean, requireCoverage?: boolean, requireMutation?: boolean, log?: object, worker?: string}} [opts]
116→ * @returns {Promise<object>} Verdict
